:"https://bionic-gpt.com/docs/running-locally/kubernetes/","support_level":"official"}],"resource_estimate_expected":{"ram_estimate_min_mb":8192,"ram_estimate_max_mb":32768,"ram_estimate_basis":"Small local model workload; model size and outputs vary.","storage_estimate_min_gb":20,"storage_estimate_max_gb":100,"storage_estimate_basis":"Small local model workload; model size and outputs vary."},"resource_estimate":{"ram_min_mb":8192,"ram_max_mb":32768,"ram_basis":"AI app stack, retrieval and local inference; model size and concurrent use drive memory.","ram_source_urls":["https://bionic-gpt.com/docs/running-locally/docker-compose/","https://bionic-gpt.com/docs/guides/managing-models/"],"storage_min_gb":20,"storage_max_gb":100,"storage_basis":"Stores application data, documents and indexes; locally stored models add space.","storage_source_urls":["https://bionic-gpt.com/docs/running-locally/docker-compose/","https://bionic-gpt.com/docs/guides/managing-models/"]},"technical_updates":{"docker":{"status":"published","checked_at":"2026-09-28","confidence":"high","note":"The project publishes its GHCR container image.","source_urls":["https://github.com/bionic-gpt/bionic-gpt/pkgs/container/bionicgpt"]},"compose":{"status":"published","checked_at":"2026-09-28","confidence":"high","note":"Official Compose setup is available for proof-of-concept use, not recommended for production.","source_urls":["https://bionic-gpt.com/docs/running-locally/docker-compose/"]},"database":{"status":"published","checked_at":"2026-09-28","confidence":"high","note":"Bionic stores app data in PostgreSQL and generated files in object storage.","source_urls":["https://github.com/bionic-gpt/bionic-gpt","https://bionic-gpt.com/docs/"]},"persistent_storage":{"status":"published","checked_at":"2026-09-28","confidence":"high","note":"Persists chat data and documents.","source_urls":["https://github.com/bionic-gpt/bionic-gpt","https://bionic-gpt.com/docs/"]},"ram":{"status":"not_published","checked_at":"2026-09-28","confidence":"low","note":"Estimated range is stored separately.","source_urls":["https://bionic-gpt.com/docs/running-locally/docker-compose/","https://bionic-gpt.com/docs/guides/managing-models/"]},"storage":{"status":"not_published","checked_at":"2026-09-28","confidence":"low","note":"Estimated range is stored separately.","source_urls":["https://bionic-gpt.com/docs/running-locally/docker-compose/","https://bionic-gpt.com/docs/guides/managing-models/"]},"docker_image":{"status":"published","checked_at":"2026-09-28","confidence":"high","note":"The project publishes its GHCR container image.","source_urls":["https://github.com/bionic-gpt/bionic-gpt/pkgs/container/bionicgpt"]}},"changes":{"summary":"Self-hosted AI workspace for team chat, document search, and workflows with connected language models.","source_model":"open_source","license":"Apache License 2.0","license_spdx_id":"Apache-2.0","license_type":"permissive","publisher_name":"Bionic GPT","publisher_type":"company","publisher_url":"https://github.com/bionic-gpt","pricing_model":"freemium","website_url":"https://bionic-gpt.com/","source_code_url":"https://github.com/bionic-gpt/bionic-gpt","source_code_host":"github","docs_url":"https://bionic-gpt.com/docs/","install_docs_url":"https://bionic-gpt.com/docs/running-locally/kubernetes/","docker_support":"official","docker_url":"https://github.com/bionic-gpt/bionic-gpt/pkgs/container/bionicgpt","docker_image":"ghcr.io/bionic-gpt/bionicgpt:latest","compose_support":true,"compose_url":"https://bionic-gpt.com/docs/running-locally/docker-compose/","requires_database":true,"database_types":["postgresql"],"persistent_storage":true,"storage_profile":"depends","deployment_methods":["docker","compose","kubernetes"],"data_source_urls":["https://github.com/bionic-gpt/bionic-gpt","https://github.com/bionic-gpt/bionic-gpt/blob/main/LICENCE","https://github.com/bionic-gpt/bionic-gpt/pkgs/container/bionicgpt","https://bionic-gpt.com/","https://bionic-gpt.com/pricing/","https://bionic-gpt.com/docs/","https://bionic-gpt.com/docs/running-locally/docker-compose/","https://bionic-gpt.com/docs/running-locally/kubernetes/","https://bionic-gpt.com/docs/guides/managing-models/"],"summary_source":"https://github.com/bionic-gpt/bionic-gpt","summary_confidence":"high","data_confidence":"high"}}]$batch$::jsonb;
begin
  for app_rec in
    select * from jsonb_to_recordset(batch) as x(
      slug text,
      expected_source_model text,
      expected_license text,
      expected_docs_url text,
      expected_categories jsonb,
      categories jsonb,
      expected_install_options jsonb,
      install_options jsonb,
      resource_estimate_expected jsonb,
      resource_estimate jsonb,
      technical_updates jsonb,
      changes jsonb
    )
  loop
    select a.id into v_app_id
    from public.self_host_apps a
    where a.slug=app_rec.slug
      and a.published is true
      and a.self_hosting_status='self_hostable'
      and a.source_model::text=app_rec.expected_source_model
      and a.license is not distinct from app_rec.expected_license
      and a.docs_url is not distinct from app_rec.expected_docs_url
    for update;
    if v_app_id is null then
      raise exception '% app record changed since review', app_rec.slug;
    end if;

    select coalesce(array_agg(c.slug order by c.slug),'{}'::text[])
      into current_categories
    from public.self_host_app_category_links l
    join public.self_host_app_categories c on c.id=l.category_id
    where l.app_id=v_app_id;
    expected_categories := array(
      select jsonb_array_elements_text(app_rec.expected_categories) order by 1
    );
    if current_categories is distinct from expected_categories then
      raise exception '% categories changed since review', app_rec.slug;
    end if;

    select io.options into current_options
    from public.self_host_app_install_options io
    where io.app_id=v_app_id
    for update;
    if current_options is distinct from app_rec.expected_install_options then
      raise exception '% install options changed since review', app_rec.slug;
    end if;

    select e.* into estimate_row
    from public.self_host_app_resource_estimates e
    where e.app_id=v_app_id
    for update;
    if not found or not (to_jsonb(estimate_row) @> app_rec.resource_estimate_expected) then
      raise exception '% resource estimate changed since review', app_rec.slug;
    end if;

    select * into app_patch
    from jsonb_populate_record(null::public.self_host_apps, app_rec.changes);

    update public.self_host_apps a set
      summary=app_patch.summary,
      source_model=app_patch.source_model,
      license=app_patch.license,
      license_spdx_id=app_patch.license_spdx_id,
      license_type=app_patch.license_type,
      publisher_name=app_patch.publisher_name,
      publisher_type=app_patch.publisher_type,
      publisher_url=app_patch.publisher_url,
      pricing_model=app_patch.pricing_model,
      website_url=app_patch.website_url,
      source_code_url=app_patch.source_code_url,
      source_code_host=app_patch.source_code_host,
      docs_url=app_patch.docs_url,
      install_docs_url=app_patch.install_docs_url,
      docker_support=app_patch.docker_support,
      docker_url=app_patch.docker_url,
      docker_image=app_patch.docker_image,
      compose_support=app_patch.compose_support,
      compose_url=app_patch.compose_url,
      requires_database=app_patch.requires_database,
      database_types=app_patch.database_types,
      persistent_storage=app_patch.persistent_storage,
      storage_profile=app_patch.storage_profile,
      deployment_methods=app_patch.deployment_methods,
      data_source_urls=app_patch.data_source_urls,
      summary_source=app_patch.summary_source,
      summary_confidence=app_patch.summary_confidence,
      data_confidence=app_patch.data_confidence,
      technical_fact_status=coalesce(a.technical_fact_status,'{}'::jsonb) || app_rec.technical_updates,
      technical_facts_checked_at=now(),
      data_checked_at=now(),
      updated_at=now()
    where a.id=v_app_id;
    get diagnostics affected = row_count;
    if affected <> 1 then raise exception '% app update failed', app_rec.slug; end if;

    update public.self_host_app_resource_estimates e set
      ram_estimate_min_mb=(app_rec.resource_estimate->>'ram_min_mb')::numeric,
      ram_estimate_max_mb=(app_rec.resource_estimate->>'ram_max_mb')::numeric,
      ram_estimate_kind='estimated',
      ram_estimate_confidence='low',
      ram_estimate_basis=app_rec.resource_estimate->>'ram_basis',
      ram_source_urls=array(select jsonb_array_elements_text(app_rec.resource_estimate->'ram_source_urls')),
      storage_estimate_min_gb=(app_rec.resource_estimate->>'storage_min_gb')::numeric,
      storage_estimate_max_gb=(app_rec.resource_estimate->>'storage_max_gb')::numeric,
      storage_estimate_kind='estimated',
      storage_estimate_confidence='low',
      storage_estimate_basis=app_rec.resource_estimate->>'storage_basis',
      storage_source_urls=array(select jsonb_array_elements_text(app_rec.resource_estimate->'storage_source_urls')),
      checked_at=now(),
      updated_at=now()
    where e.app_id=v_app_id
      and to_jsonb(e) @> app_rec.resource_estimate_expected;
    get diagnostics affected = row_count;
    if affected <> 1 then raise exception '% resource estimate update failed', app_rec.slug; end if;

    update public.self_host_app_install_options io set
      options=app_rec.install_options,
      docker_urls=array(select o->>'url' from jsonb_array_elements(app_rec.install_options) o where o->>'method'='docker' order by (o->>'sort_order')::integer),
      docker_images=array(select distinct o->>'image' from jsonb_array_elements(app_rec.install_options) o where o->>'method'='docker' and nullif(o->>'image','') is not null order by 1),
      compose_urls=array(select o->>'url' from jsonb_array_elements(app_rec.install_options) o where o->>'method'='compose' order by (o->>'sort_order')::integer),
      unraid_urls=array(select o->>'url' from jsonb_array_elements(app_rec.install_options) o where o->>'method'='unraid' order by (o->>'sort_order')::integer),
      native_urls=array(select o->>'url' from jsonb_array_elements(app_rec.install_options) o where o->>'method'='native' order by (o->>'sort_order')::integer),
      kubernetes_urls=array(select o->>'url' from jsonb_array_elements(app_rec.install_options) o where o->>'method'='kubernetes' order by (o->>'sort_order')::integer),
      source_urls=array(select distinct o->>'source_url' from jsonb_array_elements(app_rec.install_options) o where nullif(o->>'source_url','') is not null order by 1),
      checked_at=now(),
      updated_at=now()
    where io.app_id=v_app_id
      and io.options=app_rec.expected_install_options;
    get diagnostics affected = row_count;
    if affected <> 1 then raise exception '% install option update failed', app_rec.slug; end if;

    delete from public.self_host_app_category_links where app_id=v_app_id;
    insert into public.self_host_app_category_links(app_id,category_id)
    select v_app_id,c.id
    from jsonb_array_elements_text(app_rec.categories) x(slug)
    join public.self_host_app_categories c on c.slug=x.slug;
    get diagnostics affected = row_count;
    if affected <> jsonb_array_length(app_rec.categories) then
      raise exception '% category update failed', app_rec.slug;
    end if;
  end loop;
end
$migration$;

commit;
